<?php
namespace Tests\Unit;use App\Services\ProductImport\ProductNormalizer;use PHPUnit\Framework\TestCase;
class ProductNormalizerTest extends TestCase {public function test_equivalent_names_have_same_model():void{$n=new ProductNormalizer;$this->assertSame('GEL-KAYANO 32',$n->model("Asics Gel Kayano 32 Men's"));$this->assertSame('GEL-KAYANO 32',$n->model('ASICS GEL-KAYANO 32'));}public function test_multiple_brands_and_localized_terms_are_normalized():void{$n=new ProductNormalizer;$nike=$n->normalize(['name'=>'Nike Air Max 90 muške patike, crna','sku'=>'N90']);$adidas=$n->normalize(['name'=>'adidas Supernova Rise 3 W ženske patike za trčanje, plava','sku'=>'ADI3']);$this->assertSame('NIKE',$nike['brand']);$this->assertSame('AIR MAX 90',$nike['model']);$this->assertSame('ADIDAS',$adidas['brand']);$this->assertSame('SUPERNOVA RISE 3',$adidas['model']);$this->assertSame('female',$adidas['gender']);}}
